@push('scripts')
<script>document.querySelectorAll('[data-snapshot]').forEach(button=>button.addEventListener('click',()=>{const modal=document.getElementById(button.dataset.snapshot);modal.classList.add('show');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}));document.querySelectorAll('.snapshot').forEach(modal=>{const close=()=>{modal.classList.remove('show');modal.setAttribute('aria-hidden','true');document.body.style.overflow=''};modal.querySelector('.snapshot__close').addEventListener('click',close);modal.addEventListener('click',event=>{if(event.target===modal)close()})});document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.snapshot.show').forEach(modal=>modal.querySelector('.snapshot__close').click())});</script>
@endpush
